select ess.*, u.username as user_name, COALESCE(( select count(*) from user_collect uc where uc.target_type = 'elderly_station' and uc.target_id = CAST(ess.id AS CHAR) ), 0) as collect_number, CASE WHEN #{userId} IS NOT NULL AND EXISTS ( SELECT 1 FROM user_collect uc2 WHERE uc2.user_id = #{userId} AND uc2.target_type = 'elderly_station' AND uc2.target_id = CAST(ess.id AS CHAR) ) THEN 1 ELSE 0 END AS is_collect from elderly_service_subject ess LEFT JOIN sys_user u ON ess.user_id = u.id
and ess.user_id = #{merchantUserId}
and ess.name like concat('%', #{name}, '%')
and ess.business_status = #{status}
and (ess.name like concat('%', #{keyword}, '%') or ess.registered_address like concat('%', #{keyword}, '%') or ess.business_address like concat('%', #{keyword}, '%'))
order by ess.create_time desc

